doi_batch.body:
{% for group in issue_groups %}


    {{ journal_title }}
    {% if issn %}{{ issn }}{% endif %}



      {{ group.issue.publication_date|date:"Y" }}
      {{ group.issue.publication_date|date:"m" }}
      {{ group.issue.publication_date|date:"d" }}

    {% if group.issue.volume %}

      {{ group.issue.volume }}

    {% endif %}
    {% if group.issue.issue_number %}{{ group.issue.issue_number }}{% endif %}

  {% for article in group.articles %}


      {{ article.title }}

    {% if article.authors_list %}

      {% for author in article.authors_list %}

        {% if author.given %}{{ author.given }}{% endif %}
        {{ author.surname }}

      {% endfor %}

    {% endif %}

      {{ article.publication_date|date:"Y" }}
      {{ article.publication_date|date:"m" }}
      {{ article.publication_date|date:"d" }}


      {{ article.doi }}
      {{ article.absolute_url }}


  {% endfor %}

{% endfor %}
